package media

import (
	"errors"
	"github.com/fogel-dev/podhod/apps/api/internal/id"
	"io"
	"os"
	"path/filepath"
	"regexp"
)

// Storage keys are generated by the server and are never client paths.
type Storage interface {
	Put(string, []byte) error
	Open(string) (*os.File, error)
	Remove(string) error
}
type Disk struct{ Root *os.Root }

var validKey = regexp.MustCompile(`^[a-f0-9-]{36}\.(bin|jpg|tmp)$`)

func NewDisk(dir string) (*Disk, error) {
	if dir == "" || !filepath.IsAbs(dir) {
		return nil, errors.New("MEDIA_DIR must be an absolute private directory")
	}
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, err
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, err
	}
	return &Disk{root}, nil
}
func key() string { return id.New() + ".bin" }
func (d *Disk) Put(name string, data []byte) error {
	if !validKey.MatchString(name) {
		return errors.New("invalid storage key")
	}
	free, total, err := diskSpace(d.Root.Name())
	if err != nil {
		return err
	}
	if free < total/5+uint64(len(data)) {
		return errors.New("media disk space below reserve")
	}
	tmp := id.New() + ".tmp"
	f, err := d.Root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	defer d.Root.Remove(tmp)
	_, err = f.Write(data)
	if err == nil {
		err = f.Sync()
	}
	closeErr := f.Close()
	if err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return d.Root.Rename(tmp, name)
}
func (d *Disk) Open(name string) (*os.File, error) {
	if !validKey.MatchString(name) {
		return nil, errors.New("invalid storage key")
	}
	return d.Root.Open(name)
}
func (d *Disk) Remove(name string) error {
	if !validKey.MatchString(name) {
		return errors.New("invalid storage key")
	}
	e := d.Root.Remove(name)
	if errors.Is(e, os.ErrNotExist) {
		return nil
	}
	return e
}
func read(store Storage, k string) ([]byte, error) {
	f, e := store.Open(k)
	if e != nil {
		return nil, e
	}
	defer f.Close()
	b, e := io.ReadAll(io.LimitReader(f, MaxBytes+1))
	if e == nil && int64(len(b)) > MaxBytes {
		return nil, errors.New("stored image too large")
	}
	return b, e
}
